use super::*;
use semio_framework_test_fixtures::fixture_text;
#[test]
fn original_scalar_leaf_native_zero_copy_close_keeps_original_value_until_admitted_metadata(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🍃️leaf/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["metadataCopy"].as_u64().unwrap()as usize,size_of::<Option<i64>>());let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};for row in law["values"].as_array().unwrap(){let value=row.as_i64().unwrap();let mut cursor=Leaf{value:Some(value)};assert_eq!(cursor.next_work_byte_demand().unwrap(),size_of::<Option<i64>>());for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,(born,released))=crate::retirement::effect_fixture::observed(denied,|effect|cursor.close_step(0,effect));assert!(matches!(result,RetirementStep::BudgetExhausted));assert_eq!((born,released),(0,0));assert_eq!(cursor.value,Some(value));assert!(!cursor.terminal_is_empty())}let(result,(born,released))=crate::retirement::effect_fixture::observed(grant,|effect|cursor.close_step(0,effect));let RetirementStep::Progress(progress,work)=result else{panic!("leaf close did not report progress")};assert_eq!(work,1);assert_eq!((progress.copied_items,progress.copied_bytes,progress.retained_capacity_bytes,progress.released_bytes),(1,size_of::<Option<i64>>(),0,0));assert_eq!((born,released),(0,0));assert!(cursor.terminal_is_empty());assert_eq!(cursor.value,None);let(_,(born,released))=crate::allocation_testing::observe_retirement_allocations(||drop(cursor));assert_eq!((born,released),(0,0));}
}
